package xyz.shuncongci.leica

import org.junit.Assert.*
import org.junit.Rule
import org.junit.Test
import org.junit.rules.TemporaryFolder
import java.io.*
import java.nio.ByteBuffer
import java.nio.ByteOrder
import java.util.concurrent.CancellationException

/** Synthetic framing/profile regression. Not Android decoding or a gallery acceptance test. */
class HdrJpegCompatibilityTest {
    @get:Rule val temporary=TemporaryFolder()
    private val jpeg get()=CaptureMetadataFixtures.jpeg
    private val ns="urn:iso:std:iso:ts:21496:-1\u0000".toByteArray()
    private val fields="xmlns:hdrgm=\"http://ns.adobe.com/hdr-gain-map/1.0/\" hdrgm:Version=\"1.0\" hdrgm:GainMapMin=\"-2.0\" hdrgm:GainMapMax=\"2.0\" hdrgm:Gamma=\"1\" hdrgm:OffsetSDR=\"0.015625\" hdrgm:OffsetHDR=\"0.015625\" hdrgm:HDRCapacityMin=\"0\" hdrgm:HDRCapacityMax=\"3.0\" hdrgm:BaseRenditionIsHDR=\"False\""
    private fun segment(m:Int,p:ByteArray):ByteArray=ByteArrayOutputStream().also{out->DataOutputStream(out).apply{writeByte(255);writeByte(m);writeShort(p.size+2);write(p)}}.toByteArray()
    private fun xmp(attrs:String,body:String="")=segment(0xe1,PreservedMetadata.XMP+("<x:xmpmeta xmlns:x=\"adobe:ns:meta/\"><rdf:RDF xmlns:rdf=\"http://www.w3.org/1999/02/22-rdf-syntax-ns#\"><rdf:Description rdf:about=\"\" $attrs>$body</rdf:Description></rdf:RDF></x:xmpmeta>").toByteArray())
    /** Independent pre-ISO writer profile/MPF, not generated by the candidate writer. */
    private fun legacy(gm:String=fields,base:ByteArray=jpeg,gain:ByteArray=jpeg,mainIso:Boolean=false,afterIndex:Boolean=false,little:Boolean=false,gainExtra:ByteArray=ByteArray(0),directoryExtra:String="",rawGainXmp:ByteArray?=null):ByteArray {
        val gx=(rawGainXmp?.let{segment(0xe1,PreservedMetadata.XMP+it)}?:xmp(gm))+gainExtra;val gl=gain.size+gx.size
        val px=xmp("xmlns:hdrgm=\"http://ns.adobe.com/hdr-gain-map/1.0/\" hdrgm:Version=\"1.0\" xmlns:Container=\"http://ns.google.com/photos/1.0/container/\" xmlns:Item=\"http://ns.google.com/photos/1.0/container/item/\" $directoryExtra",
            "<Container:Directory><rdf:Seq><rdf:li rdf:parseType=\"Resource\"><Container:Item Item:Semantic=\"Primary\" Item:Mime=\"image/jpeg\"/></rdf:li><rdf:li rdf:parseType=\"Resource\"><Container:Item Item:Semantic=\"GainMap\" Item:Mime=\"image/jpeg\" Item:Length=\"$gl\"/></rdf:li></rdf:Seq></Container:Directory>")
        val pi=if(mainIso)segment(0xe2,ns+byteArrayOf(0,0,0,0))else ByteArray(0)
        val size=base.size+px.size+pi.size+90;val before=if(afterIndex)pi else px+pi
        val p=ByteBuffer.allocate(86).order(if(little)ByteOrder.LITTLE_ENDIAN else ByteOrder.BIG_ENDIAN)
        p.put(byteArrayOf(77,80,70,0));p.put(if(little)byteArrayOf(73,73)else byteArrayOf(77,77));p.putShort(42);p.putInt(8);p.putShort(3)
        p.putShort(0xb000.toShort());p.putShort(7);p.putInt(4);p.put("0100".toByteArray())
        p.putShort(0xb001.toShort());p.putShort(4);p.putInt(1);p.putInt(2)
        p.putShort(0xb002.toShort());p.putShort(7);p.putInt(32);p.putInt(50);p.putInt(0)
        p.putInt(0x030000);p.putInt(size);p.putInt(0);p.putShort(0);p.putShort(0)
        p.putInt(0);p.putInt(gl);p.putInt(size-(2+before.size+8));p.putShort(0);p.putShort(0)
        val primary=before+segment(0xe2,p.array())+(if(afterIndex)px else ByteArray(0))
        return base.copyOfRange(0,2)+primary+base.copyOfRange(2,base.size)+gain.copyOfRange(0,2)+gx+gain.copyOfRange(2,gain.size)
    }
    private data class Header(val at:Int,val end:Int,val marker:Int,val payload:ByteArray)
    private fun headers(b:ByteArray,start:Int=0):List<Header>{
        val out=ArrayList<Header>();var at=start+2
        while(true){assertEquals(255,b[at].toInt()and 255);while((b[at+1].toInt()and 255)==255)at++
            val m=b[at+1].toInt()and 255;if(m==0xda || m==0xd9)return out
            val n=((b[at+2].toInt()and 255)shl 8)+(b[at+3].toInt()and 255);val end=at+2+n
            out.add(Header(at,end,m,b.copyOfRange(at+4,end)));at=end}
    }
    private fun isIso(h:Header)=h.marker==0xe2 && PreservedMetadata.starts(h.payload,ns)
    private fun mpf(b:ByteArray)=headers(b).single{it.marker==0xe2 && PreservedMetadata.starts(it.payload,byteArrayOf(77,80,70,0))}
    private fun table(b:ByteArray):ByteBuffer {val h=mpf(b);return ByteBuffer.wrap(h.payload).order(if(h.payload[4]==73.toByte())ByteOrder.LITTLE_ENDIAN else ByteOrder.BIG_ENDIAN)}
    private fun primary(b:ByteArray)=table(b).getInt(58)
    private fun image(b:ByteArray,start:Int,end:Int):ByteArray {
        val out=ByteArrayOutputStream();out.write(b,start,2);var at=start+2
        for(h in headers(b,start)){out.write(b,at,h.at-at);if(h.marker !in 0xe0..0xef && h.marker!=0xfe)out.write(b,h.at,h.end-h.at);at=h.end}
        out.write(b,at,end-at);return out.toByteArray()
    }
    private fun source(b:ByteArray)=temporary.newFile().apply{writeBytes(b)}
    private fun convert(b:ByteArray):ByteArray {
        val f=source(b);var used:File?=null
        val result=HdrJpegCompatibility.withCompatible(f,temporary.root,Cancel()){used=it;it.readBytes()}
        assertArrayEquals(b,f.readBytes());if(used!=f)assertFalse(used!!.exists());return result
    }
    private fun checkConverted(before:ByteArray,after:ByteArray){
        val a=primary(before);val n=primary(after);val t=table(after)
        assertEquals(n,mpf(after).at+8+t.getInt(78));assertEquals(after.size,n+t.getInt(74))
        assertArrayEquals(image(before,0,a),image(after,0,n));assertArrayEquals(image(before,a,before.size),image(after,n,after.size))
        assertEquals(1,headers(after).count(::isIso));assertEquals(1,headers(after,n).count(::isIso))
        assertArrayEquals(HdrIsoMetadata.primary(),headers(after).single(::isIso).payload)
        assertArrayEquals(HdrIsoMetadata.gainLog2(-2.0,2.0,3.0),headers(after,n).single(::isIso).payload)
        assertTrue(String(after,Charsets.ISO_8859_1).contains("Item:Length=\"${t.getInt(74)}\""))
    }
    private fun noChange(b:ByteArray){val f=source(b);HdrJpegCompatibility.withCompatible(f,temporary.root,Cancel()){assertSame(f,it)};assertArrayEquals(b,f.readBytes())}
    @Test fun legacyHasOnlyAdobeAndDirectBytesLackIso(){val b=legacy();assertEquals(0,headers(b).count(::isIso));assertEquals(0,headers(b,primary(b)).count(::isIso));assertTrue(String(b).contains("hdrgm:GainMapMin"))}
    @Test fun legacyCacheGetsBothDeclarationsWithoutReencoding(){val b=legacy();checkConverted(b,convert(b))}
    @Test fun primaryOnlyVersionIsNotMistakenForFullIso(){val b=legacy(mainIso=true);checkConverted(b,convert(b))}
    @Test fun mpfLittleEndianIsPreserved(){val b=legacy(little=true);checkConverted(b,convert(b));assertEquals(73,mpf(convert(b)).payload[4].toInt())}
    @Test fun xmpAfterMpfHasCorrectRelativeOffset(){val b=legacy(afterIndex=true);checkConverted(b,convert(b))}
    @Test fun littleEndianXmpAfterMpf(){val b=legacy(afterIndex=true,little=true,mainIso=true);checkConverted(b,convert(b))}
    @Test fun repeatedSaveIsByteExactAndNoSecondCopy(){val b=convert(legacy());noChange(b);assertArrayEquals(b,convert(b))}
    @Test fun newEncoderAlreadyDualIsUntouched(){val out=ByteArrayOutputStream();UltraHdrContainer.write(out,jpeg,jpeg,HdrMath.Map(16,12,IntArray(0),.25f,4f,8f));noChange(out.toByteArray())}
    @Test fun unknownIsoGainVersionNotOverwritten(){noChange(legacy(gainExtra=segment(0xe2,ns+byteArrayOf(0,1,0,1))))}
    @Test fun unknownPrimaryVersionNotOverwritten(){val b=legacy(mainIso=true);val h=headers(b).single(::isIso);b[h.end-1]=1;noChange(b)}
    @Test fun nonUnitGammaProfileIsNotGuessed(){noChange(legacy(gm=fields.replace("Gamma=\"1\"","Gamma=\"2\"")))}
    @Test fun nonAppOffsetsNotGuessed(){noChange(legacy(gm=fields.replace("OffsetSDR=\"0.015625\"","OffsetSDR=\"0.0\"")))}
    @Test fun hdrBaseProfileNotConverted(){noChange(legacy(gm=fields.replace("IsHDR=\"False\"","IsHDR=\"True\"")))}
    @Test fun nonzeroBaseHeadroomNotConverted(){noChange(legacy(gm=fields.replace("HDRCapacityMin=\"0\"","HDRCapacityMin=\"1\"")))}
    @Test fun unknownGainAttributeNotDropped(){noChange(legacy(gm=fields+" hdrgm:Unknown=\"1\""))}
    @Test fun conflictingPrimaryGainAttributeNotConverted(){noChange(legacy(directoryExtra="hdrgm:Gamma=\"2\""))}
    @Test fun invalidGainsNeverCreateIso(){for(s in listOf("NaN","Infinity","-150","129"))noChange(legacy(gm=fields.replace("GainMapMin=\"-2.0\"","GainMapMin=\"$s\"")))}
    @Test fun contradictoryBoundsNeverCreateIso(){noChange(legacy(gm=fields.replace("GainMapMin=\"-2.0\"","GainMapMin=\"3.0\"")))}
    @Test fun duplicatedXmpNotInterpreted(){noChange(legacy(gainExtra=xmp(fields)))}
    @Test fun missingGainProfileNotInterpreted(){noChange(legacy(gm="xmlns:dc=\"http://purl.org/dc/elements/1.1/\" dc:title=\"unknown\""))}
    @Test fun malformedXmlDoesNotReplaceOriginal(){noChange(legacy(gm=fields+" broken=\"<\""))}
    @Test fun dtdAndExternalEntityAreRejected(){val xml="<!DOCTYPE x [<!ENTITY v SYSTEM 'file:///never-read'>]><x/>";noChange(legacy(rawGainXmp=xml.toByteArray()))}
    @Test fun utf16DtdCannotBypassUtf8ProfileGuard(){val packet=xmp(fields);val text=String(packet.copyOfRange(4+PreservedMetadata.XMP.size,packet.size),Charsets.UTF_8);val xml="<?xml version=\"1.0\" encoding=\"UTF-16BE\"?><!DOCTYPE x:xmpmeta [<!ENTITY v SYSTEM 'file:///never-read'>]>"+text;noChange(legacy(rawGainXmp=xml.toByteArray(Charsets.UTF_16BE)))}
    @Test fun extraTrailingDataIsNotSilentlyTrimmed(){noChange(legacy()+byteArrayOf(1,2,3))}
    @Test fun truncatedGainRemainsUnmodified(){val b=legacy();noChange(b.copyOf(b.size-1))}
    @Test fun wrongMpfGainOffsetIsNotRepairedByGuess(){val b=legacy();val h=mpf(b);b[h.at+4+81]=(b[h.at+4+81].toInt()+1).toByte();noChange(b)}
    @Test fun wrongDirectoryLengthIsNotGuessed(){val b=legacy();val s=String(b,Charsets.ISO_8859_1);val at=s.indexOf("Item:Length=\"")+13;b[at]=57;noChange(b)}
    @Test fun plainSdrDoesNotAcquireGainMetadata(){noChange(jpeg)}
    @Test fun invalidContainerIsNotUpgraded(){noChange(byteArrayOf(1,2,3,4))}
    @Test fun compressedStreamsCross64KiBIntact(){val extra=segment(0xfe,ByteArray(65520){(it%251).toByte()});val base=jpeg.copyOfRange(0,2)+extra+jpeg.copyOfRange(2,jpeg.size);val b=legacy(base=base,gain=base);checkConverted(b,convert(b))}
    @Test fun markerFillBytesAndIndicesStayExact(){val base=jpeg.copyOfRange(0,2)+byteArrayOf(-1,-1)+jpeg.copyOfRange(2,jpeg.size);val b=legacy(base=base,gain=base);checkConverted(b,convert(b))}
    @Test fun privateCopyScopedToSynchronousPublisher(){val f=source(legacy());var privateCopy:File?=null;val returned=HdrJpegCompatibility.withCompatible(f,temporary.root,Cancel()){assertNotEquals(f,it);assertTrue(it.isFile);privateCopy=it;"done"};assertEquals("done",returned);assertFalse(privateCopy!!.exists());assertTrue(f.exists())}
    @Test fun publisherIoFailurePropagatesAndCleans(){val b=legacy();val f=source(b);var copy:File?=null;assertThrows(IOException::class.java){HdrJpegCompatibility.withCompatible(f,temporary.root,Cancel()){copy=it;throw IOException("fixture publish IO")}};assertFalse(copy!!.exists());assertArrayEquals(b,f.readBytes())}
    @Test fun cancellationBeforeOpenDoesNotTouchMissingSource(){assertThrows(CancellationException::class.java){HdrJpegCompatibility.withCompatible(File(temporary.root,"missing"),temporary.root,Cancel().apply{cancelled=true}){fail("not published")}}}
    @Test fun publisherCancellationCleansOnlyPrivateCopy(){val f=source(legacy());val c=Cancel();var copy:File?=null;assertThrows(CancellationException::class.java){HdrJpegCompatibility.withCompatible(f,temporary.root,c){copy=it;c.cancelled=true;c.check()}};assertFalse(copy!!.exists());assertTrue(f.exists())}
    @Test fun inputIoFailureIsNotSilentlyPassedThrough(){assertThrows(FileNotFoundException::class.java){HdrJpegCompatibility.withCompatible(File(temporary.root,"missing"),temporary.root,Cancel()){fail("not published")}}}
    @Test fun privateDestinationIoFailureDoesNotPublish(){val b=legacy();val f=source(b);assertThrows(IOException::class.java){HdrJpegCompatibility.withCompatible(f,File(temporary.root,"missing-dir"),Cancel()){fail("not published")}};assertArrayEquals(b,f.readBytes())}
    @Test fun existingFilesInDirectoryAreNotReplaced(){val keep=temporary.newFile().apply{writeText("keep")};convert(legacy());assertEquals("keep",keep.readText())}
    @Test fun metadataAndBadgeRewriteThenCompatibilityPreservesArchive(){
        val original=source(jpeg);val bundle=PreservedMetadata.read(original,Cancel())
        for(badge in listOf(false,true)){
            val encoded=source(legacy());val out=File(temporary.newFolder(),"output.jpg")
            CaptureMetadataContainer.writePreserved(encoded,out,bundle,16,12,badge,Cancel())
            val before=out.readBytes();val after=convert(before);checkConverted(before,after)
            val copy=source(after);assertArrayEquals(PreservedMetadata.archive(bundle),PreservedMetadata.readArchive(copy,Cancel()))
            assertArrayEquals(CaptureMetadataContainer.readExif(out).exif,CaptureMetadataContainer.readExif(copy).exif)
        }
    }
    @Test fun rawLogParametersAvoidFloatRoundTrip(){val lo=-2.753456789123;val hi=2.300453456789;val cap=2.707123456789;val p=ByteBuffer.wrap(HdrIsoMetadata.gainLog2(lo,hi,cap),ns.size,77).slice();p.position(17);assertEquals(lo,p.int/(1 shl 23).toDouble(),6e-8);assertEquals(hi,p.int/(1 shl 23).toDouble(),6e-8)}
}
